predicted_sql:
SELECT ROUND(
    100.0 * COUNT(DISTINCT CASE WHEN language = 'Chinese Simplified' THEN uuid END)
    / (SELECT COUNT(*) FROM cards),
    2
) AS percentage
FROM foreign_data;

SELECT DISTINCT replace(replace(text, char(10), ' '), char(13), ' ') AS text
FROM cards
WHERE name = 'Benalish Knight';

SELECT COUNT(DISTINCT scryfallOracleId)
FROM cards
WHERE (',' || promoTypes || ',') LIKE '%,release,%';

SELECT COUNT(DISTINCT language) AS language_count
FROM foreign_data
WHERE uuid IN (SELECT uuid FROM cards WHERE name = 'Swamp');

SELECT ROUND(
    100.0 * SUM(CASE WHEN Tags LIKE '%<r>%' THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage
FROM posts
WHERE OwnerUserId = -1;

SELECT ROUND(
    100.0 * SUM(CASE WHEN NOT EXISTS (
        SELECT 1
        FROM "member" AS m
        WHERE m.link_to_major = major.major_id
    ) THEN 1 ELSE 0 END) / COUNT(*),
    2
) AS percentage_of_majors_without_members
FROM major;

SELECT ROUND(
    100.0 * SUM(CASE WHEN Birthday >= '1960-01-01' THEN 1 ELSE 0 END) / COUNT(*),
    1
) AS percentage
FROM Patient
WHERE LOWER(Diagnosis) = 'psoriatic arthritis';
